css:
.emc { direction: rtl; font-family: 'Noto Naskh Arabic','Amiri','Tahoma',sans-serif; font-size: 10px; color: #1f2933; }
.emc table { width: 100%; border-collapse: collapse; }
.emc-title { background: #12355b; color: #fff; text-align: center; padding: 6px; border-radius: 6px; margin-bottom: 6px; }
.emc-title-ar { font-size: 16px; font-weight: bold; }
.emc-title-en { font-size: 11px; opacity: .85; }
.emc-meta { font-size: 10px; margin-top: 3px; }
.emc-head { margin-bottom: 6px; }
.emc-head th, .emc-head td { border: 1px solid #cfd8e3; padding: 3px 6px; text-align: right; }
.emc-head th { background: #eef3f8; width: 13%; white-space: nowrap; }
.emc-img { width: 18%; text-align: center !important; }
.emc-img img { max-width: 100%; max-height: 90px; }
.emc-days-wrap > tbody > tr > td.emc-half { width: 50%; vertical-align: top; padding: 0 2px; }
.emc-days th { background: #12355b; color: #fff; padding: 3px; border: 1px solid #12355b; }
.emc-days td { border: 1px solid #dfe5ec; padding: 2px 3px; text-align: center; height: 15px; }
.emc-days td.num { font-weight: bold; }
.emc-days tr.fri td { background: #fff1db; }
.emc-days tr.off td { color: #b42318; }
.emc-totals { margin-top: 6px; }
.emc-totals td { border: 1px solid #cfd8e3; text-align: center; padding: 4px; }
.emc-totals span { display: block; font-size: 9px; color: #52606d; }
.emc-totals b { font-size: 13px; }
.emc-totals td.amount { background: #e6f4ea; }
.emc-totals td.amount b { color: #137333; font-size: 15px; }
.emc-notes { border: 1px solid #cfd8e3; padding: 4px 6px; margin-top: 6px; }
.emc-sign { margin-top: 10px; }
.emc-sign td { width: 33%; text-align: center; padding: 4px 10px; }
.emc-sign .t { font-weight: bold; }
.emc-sign .n { margin-top: 3px; min-height: 12px; }
.emc-sign .l { border-bottom: 1px solid #52606d; height: 28px; margin: 0 20px; }
@page { size: A4 landscape; margin: 8mm; }

html:
{% set months = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'] %}
{% set days = doc.days or [] %}
{% set half = ((days|length) + 1) // 2 %}
{% set hs = 'background-color:#12355b !important;color:#ffffff !important;font-weight:bold !important;font-size:11px !important;padding:5px 3px !important;border:1px solid #12355b !important;text-align:center !important;opacity:1 !important;-webkit-print-color-adjust:exact;print-color-adjust:exact;' %}

<style>
  @page { size: A4 landscape; margin: 6mm; }
  .print-format { padding: 0 !important; margin: 0 !important; max-width: 100% !important; width: 100% !important; }
  .print-format-gutter { padding: 0 !important; }

  .emc { direction: rtl; font-family: 'Noto Naskh Arabic','Amiri','Tahoma',sans-serif; font-size: 11px; color: #1f2933; width: 100%; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .emc table { width: 100%; border-collapse: collapse; margin: 0; }

  .emc-lh { margin-bottom: 4mm; text-align: center; }
  .emc-lh img { max-height: 22mm; max-width: 100%; }

  .emc-title { background: #12355b !important; text-align: center; padding: 2.5mm; border-radius: 2mm; margin-bottom: 3mm; }
  .emc-title * { color: #fff !important; }
  .emc-title-ar { font-size: 18px; font-weight: bold; }
  .emc-title-en { font-size: 11px; }
  .emc-meta { font-size: 11px; margin-top: 1mm; }

  .emc-head { margin-bottom: 3mm !important; }
  .emc-head th, .emc-head td { border: 1px solid #cfd8e3 !important; padding: 1.5mm 2.5mm !important; text-align: right; vertical-align: middle; font-size: 11px; }
  .emc-head th { background: #eef3f8 !important; color: #12355b !important; width: 12%; white-space: nowrap; font-weight: bold; }
  .emc-img { width: 16%; text-align: center !important; padding: 1mm !important; }
  .emc-img img { max-width: 100%; max-height: 26mm; }

  .emc-days-wrap td.emc-half { width: 50%; vertical-align: top; padding: 0 1mm !important; border: none !important; }
  .emc-days td { border: 1px solid #dfe5ec !important; padding: 0 2px !important; text-align: center; height: 6.2mm; font-size: 11px; }
  .emc-days td.num { font-weight: bold; }
  .emc-days tr.fri td { background: #fff1db !important; }
  .emc-days tr.off td { color: #b42318 !important; }

  .emc-totals { margin-top: 3mm !important; border-collapse: separate !important; border-spacing: 2mm 0; }
  .emc-totals td { width: 25%; border: 1.5px solid #12355b !important; border-radius: 2mm; text-align: center; padding: 2mm 1mm !important; background: #f7f9fc !important; }
  .emc-totals .lbl { display: block; font-size: 11px; color: #12355b; font-weight: bold; margin-bottom: 1mm; }
  .emc-totals .val { display: block; font-size: 18px; font-weight: bold; color: #1f2933; }
  .emc-totals td.amount { background: #e6f4ea !important; border-color: #137333 !important; }
  .emc-totals td.amount .lbl, .emc-totals td.amount .val { color: #137333; }
  .emc-totals td.amount .val { font-size: 20px; }

  .emc-notes { border: 1px solid #cfd8e3; padding: 1.5mm 2.5mm; margin-top: 3mm; }

  .emc-sign { margin-top: 4mm !important; }
  .emc-sign td { width: 33%; text-align: center; padding: 0 6mm !important; border: none !important; }
  .emc-sign .t { font-weight: bold; font-size: 12px; color: #12355b; }
  .emc-sign .n { margin-top: 1mm; min-height: 4mm; }
  .emc-sign .l { border-bottom: 1px solid #52606d; height: 10mm; }
</style>

<div class="emc">
  {% if letter_head %}<div class="emc-lh">{{ letter_head }}</div>{% endif %}

  <div class="emc-title">
    <div class="emc-title-ar">كارت تشغيل معدة شهري</div>
    <div class="emc-title-en">Equipment Monthly Operation Card</div>
    <div class="emc-meta">
      رقم الكارت: <b>{{ doc.name }}</b> &nbsp;|&nbsp;
      الشهر: <b>{{ months[(doc.month|int) - 1] if doc.month else '' }} {{ doc.year }}</b> &nbsp;|&nbsp;
      الوردية: <b>{{ doc.shift or '' }}</b>
    </div>
  </div>

  <table class="emc-head">
    <tr>
      <td class="emc-img" rowspan="4">
        {% if doc.image %}<img src="{{ doc.image }}">{% endif %}
      </td>
      <th>المعدة</th><td>{{ doc.equipment_name or '' }}</td>
      <th>المشروع</th><td>{{ doc.project_name or doc.project or '' }}</td>
    </tr>
    <tr>
      <th>نوع المعدة</th><td>{{ doc.equipment_type or '' }}</td>
      <th>الموقع</th><td>{{ doc.site_location or '' }}</td>
    </tr>
    <tr>
      <th>الملكية</th><td>{{ doc.ownership or '' }}</td>
      <th>السائق / المشغّل</th><td>{{ doc.operator_name or '' }}</td>
    </tr>
    <tr>
      <th>المالك</th><td>{{ doc.supplier or '' }}</td>
      <th>الفترة</th><td>{{ frappe.utils.formatdate(doc.from_date) }} - {{ frappe.utils.formatdate(doc.to_date) }}</td>
    </tr>
  </table>

  <table class="emc-days-wrap"><tr>
  {% for part in [days[:half], days[half:]] %}
    <td class="emc-half">
      <table class="emc-days">
        <tr>
          <td style="{{ hs }} width:6%;">م</td>
          <td style="{{ hs }} width:12%;">التاريخ</td>
          <td style="{{ hs }} width:13%;">اليوم</td>
          <td style="{{ hs }} width:12%;">الحالة</td>
          <td style="{{ hs }} width:11%;">الساعات</td>
          <td style="{{ hs }} width:23%;">سبب التوقف</td>
          <td style="{{ hs }} width:23%;">ملاحظات</td>
        </tr>
        {% for r in part %}
          <tr class="{% if r.day_name == 'الجمعة' %}fri{% endif %} {% if r.day_status != 'عمل' %}off{% endif %}">
            <td>{{ r.idx }}</td>
            <td>{{ frappe.utils.formatdate(r.operation_date, 'dd-MM') }}</td>
            <td>{{ r.day_name or '' }}</td>
            <td>{{ r.day_status or '' }}</td>
            <td class="num">{% if (r.working_hours or 0) > 0 %}{{ '%.1f'|format(r.working_hours) }}{% else %}-{% endif %}</td>
            <td>{{ r.idle_reason or '' }}</td>
            <td>{{ r.notes or '' }}</td>
          </tr>
        {% endfor %}
        {% if part|length < half %}
          <tr><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td></tr>
        {% endif %}
      </table>
    </td>
  {% endfor %}
  </tr></table>

  <table class="emc-totals"><tr>
    <td><span class="lbl">إجمالي ساعات التشغيل</span><span class="val">{{ '%.1f'|format(doc.total_working_hours or 0) }}</span></td>
    <td><span class="lbl">أيام العمل</span><span class="val">{{ doc.working_days or 0 }}</span></td>
    {% if doc.card_direction == "مؤجَّرة لعميل" %}
    <td><span class="lbl">سعر العميل ({{ doc.customer_rate_type or '' }})</span><span class="val">{{ frappe.utils.fmt_money(doc.customer_rate or 0) }}</span></td>
    <td class="amount"><span class="lbl">القيمة الإجمالية</span><span class="val">{{ frappe.utils.fmt_money(doc.customer_amount or 0) }}</span></td>
    {% else %}
    <td><span class="lbl">السعر ({{ doc.rate_type or '' }})</span><span class="val">{{ frappe.utils.fmt_money(doc.rate or 0) }}</span></td>
    <td class="amount"><span class="lbl">القيمة الإجمالية</span><span class="val">{{ frappe.utils.fmt_money(doc.amount or 0) }}</span></td>
    {% endif %}
  </tr></table>

  {% if doc.general_notes %}
  <div class="emc-notes"><b>ملاحظات:</b> {{ doc.general_notes }}</div>
  {% endif %}

  <table class="emc-sign"><tr>
    <td><div class="t">توقيع السائق / المشغّل</div><div class="n">{{ doc.operator_name or '' }}</div><div class="l"></div></td>
    <td><div class="t">اعتماد المشرف الميداني</div><div class="n">&nbsp;</div><div class="l"></div></td>
    <td><div class="t">اعتماد مدير المشروع</div><div class="n">&nbsp;</div><div class="l"></div></td>
  </tr></table>
</div>
